<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';Auth::requireLogin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action']??'';if($action==='delete'){$db->prepare('DELETE FROM comments WHERE id=?')->execute([$id]);flash('success','Comentário excluído.');}elseif(in_array($action,['approved','rejected','pending'],true)){$db->prepare('UPDATE comments SET status=?,moderated_at=NOW(),moderated_by=? WHERE id=?')->execute([$action,Auth::user()['id'],$id]);flash('success','Situação atualizada.');}redirect('comments.php');}$filter=$_GET['status']??'pending';if(!in_array($filter,['pending','approved','rejected','all'],true))$filter='pending';$sql='SELECT * FROM comments'.($filter==='all'?'':' WHERE status='.$db->quote($filter)).' ORDER BY created_at DESC';$rows=$db->query($sql)->fetchAll();require __DIR__.'/_header.php';?>
<div class="page-title"><div><h1>Mural</h1><p>Aprove, rejeite ou exclua mensagens dos visitantes.</p></div><div class="filters"><?php foreach(['pending'=>'Pendentes','approved'=>'Aprovados','rejected'=>'Rejeitados','all'=>'Todos'] as $key=>$label):?><a class="<?=$filter===$key?'active':''?>" href="?status=<?=$key?>"><?=$label?></a><?php endforeach;?></div></div><div class="panel comments-admin"><?php if(!$rows):?><p>Nenhum comentário nesta situação.</p><?php endif;?><?php foreach($rows as $r):?><article><div><strong><?=e($r['visitor_name'])?></strong><small><?=e($r['email'])?> • <?=format_date($r['created_at'],true)?></small><p><?=nl2br(e($r['message']))?></p><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></div><div class="comment-actions"><?php foreach(['approved'=>'Aprovar','rejected'=>'Rejeitar','pending'=>'Pendente','delete'=>'Excluir'] as $action=>$label):?><form method="post" <?=$action==='delete'?'onsubmit="return confirm(\'Excluir definitivamente?\')"':''?>><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="<?=$action?>"><button class="<?=$action==='delete'?'danger':''?>"><?=$label?></button></form><?php endforeach;?></div></article><?php endforeach;?></div><?php require __DIR__.'/_footer.php';?>
